define('taoQtiItem/qtiXmlRenderer/renderers/ResponseProcessingPerInteractionRP',['lodash', 'tpl!taoQtiItem/qtiXmlRenderer/tpl/responseProcessing', 'tpl!taoQtiItem/qtiXmlRenderer/tpl/responses/item_score', 'taoQtiItem/qtiXmlRenderer/helper/responseProcessingTpl'], function (_, tpl, itemScoreTpl, responseProcessingTpl) {
  'use strict';

  var renderFeedbackRules = (renderer, response) => {
    var ret = [];
    _.forEach(response.getFeedbackRules(), rule => {
      ret.push(rule.render(renderer));
    });
    return ret;
  };
  return {
    qtiClass: 'responseProcessing',
    template: tpl,
    getData: function getData(responseProcessing, data) {
      var defaultData = {};
      if (responseProcessing.processingType === 'custom') {
        defaultData.custom = true;
        defaultData.xml = responseProcessing.xml;
      } else {
        var interactions = responseProcessing.getRootElement().getInteractions();
        defaultData.responseRules = [];
        var outcomeIdentifiers = [];
        _.forEach(interactions, interaction => {
          var response = interaction.getResponseDeclaration();
          var outcomeIdentifier = "SCORE_".concat(response.id());
          var responseRule = responseProcessingTpl.renderInteractionRp(response, outcomeIdentifier);
          if (_.isString(responseRule) && responseRule.trim()) {
            defaultData.responseRules.push(responseRule);
            outcomeIdentifiers.push(outcomeIdentifier);
          }
        });
        defaultData.feedbackRules = [];
        _.forEach(interactions, interaction => {
          defaultData.feedbackRules = _.union(defaultData.feedbackRules, renderFeedbackRules(this, interaction.getResponseDeclaration()));
        });
        if (outcomeIdentifiers.length) {
          defaultData.responseRules.push(itemScoreTpl({
            identifier: 'SCORE',
            outcomeIdentifiers
          }));
        }
        if (defaultData.responseRules.length || defaultData.feedbackRules.length) {
          defaultData.templateDriven = true;
        }
      }
      return _.merge(data || {}, defaultData);
    }
  };
});
