define('taoQtiItem/qtiCreator/context/plugins/content/windowResizer',['jquery', 'lodash', 'core/plugin'], function ($, _, pluginFactory) {
  'use strict';

  var $window = $(window),
    pluginName = 'windowResizer',
    ns = '.itemcreatorwindowresizer',
    throttleDelayMs = 200;
  return pluginFactory({
    name: pluginName,
    init: function init() {
      var qtiCreatorContext = this.getHost();
      $window.on('resize' + ns, _.throttle(function () {
        qtiCreatorContext.trigger('resize');
      }, throttleDelayMs));
    },
    destroy: function destroy() {
      $window.off('resize' + ns);
    }
  });
});
