define('taoQtiItem/qtiCreator/widgets/static/modalFeedback/Widget',['jquery', 'taoQtiItem/qtiCreator/widgets/static/Widget', 'taoQtiItem/qtiCreator/widgets/static/modalFeedback/states/states', 'tpl!taoQtiItem/qtiCreator/tpl/toolbars/okButton'], function ($, Widget, states, okButtonTpl) {
  'use strict';

  var ModalFeedbackWidget = Widget.clone();
  ModalFeedbackWidget.initCreator = function () {
    Widget.initCreator.call(this);
    this.registerStates(states);
    this.createOkButton();
  };
  ModalFeedbackWidget.buildContainer = function () {
    this.$container = this.$original.addClass('widget-box');
  };
  ModalFeedbackWidget.createToolbar = function () {
    return this;
  };
  ModalFeedbackWidget.createOkButton = function () {
    var _this = this;
    this.$container.append($(okButtonTpl()).on('click.qti-widget', function (e) {
      e.stopPropagation();
      _this.changeState('sleep');
    }));
  };
  return ModalFeedbackWidget;
});
