define('taoQtiItem/qtiCreator/widgets/choices/inlineChoice/states/Question',['jquery', 'lodash', 'ckeditor', 'services/features', 'taoQtiItem/qtiCreator/widgets/states/factory', 'taoQtiItem/qtiCreator/widgets/choices/states/Question', 'taoQtiItem/qtiCreator/widgets/choices/helpers/formElement', 'taoQtiItem/qtiCreator/editor/ckEditor/htmlEditor', 'taoQtiItem/qtiCreator/editor/gridEditor/content'], function ($, _, CKEditor, features, stateFactory, QuestionState, formElement, htmlEditor, contentHelper) {
  'use strict';

  var ChoiceStateQuestion = stateFactory.extend(QuestionState, function initStateQuestion() {
    this.buildEditor();
  }, function exitStateQuestion() {
    this.destroyEditor();
  });
  ChoiceStateQuestion.prototype.createToolbar = function () {
    var _widget = this.widget,
      $toolbar = _widget.$container.find('td:last');
    if (features.isVisible('taoQtiItem/creator/interaction/inlineChoice/property/shuffle')) {
      formElement.initShufflePinToggle(_widget);
    }
    formElement.initDelete(_widget);
    return $toolbar;
  };
  ChoiceStateQuestion.prototype.buildEditor = function () {
    var _widget = this.widget,
      container = _widget.element.getBody(),
      $editable = _widget.$container.find('.editable-content'),
      $editableContainer = _widget.$container.find('.editable-container');
    $editableContainer.attr('data-html-editable-container', true);
    $editable.attr('data-html-editable', true).attr('contenteditable', true);
    if (!htmlEditor.hasEditor($editableContainer)) {
      htmlEditor.buildEditor($editableContainer, {
        change: contentHelper.getChangeCallback(container),
        data: {
          container,
          widget: _widget
        },
        toolbar: [{
          name: 'insert',
          items: ['SpecialChar']
        }],
        qtiMedia: false,
        qtiImage: false,
        qtiInclude: false,
        enterMode: CKEditor.ENTER_BR,
        shieldInnerContent: false,
        mathJax: false,
        furiganaPlugin: true,
        on: {
          key: function key(evt) {
            var domEvent = evt.data.domEvent.$;
            var isCtrlPressed = domEvent.ctrlKey || domEvent.metaKey;
            var key = (domEvent.key || '').toLowerCase();
            var blockedKeys = ['b', 'i', 'u', 'k', 'l'];
            if (isCtrlPressed && blockedKeys.includes(key)) {
              evt.cancel();
              domEvent.preventDefault();
            }
          }
        }
      });
    }
    $editable.on('focus.qti-widget', function () {
      _widget.changeState('choice');
    }).on('keypress.qti-widget', function (e) {
      if (e.which === 13) {
        e.preventDefault();
        $(this).blur();
        _widget.changeState('question');
      }
    });
  };
  ChoiceStateQuestion.prototype.destroyEditor = function () {
    this.widget.$container.find('.editable-content').removeAttr('contenteditable').removeAttr('data-html-editable').off('keyup.qti-widget');
    this.widget.$container.find('.editable-container').removeAttr('data-html-editable');
  };
  return ChoiceStateQuestion;
});
