define('taoQtiItem/qtiXmlRenderer/renderers/Figcaption',['tpl!taoQtiItem/qtiXmlRenderer/tpl/element'], function (tpl) {
  return {
    qtiClass: 'figcaption',
    template: tpl,
    getData: function getData(figure, data) {
      var ns = figure.getNamespace();
      if (ns && ns.name) {
        data.tag = "".concat(ns.name, ":figcaption");
      }
      return data;
    }
  };
});
